DROP TABLE IF EXISTS `v_inventory_transaction`;
/*!50001 DROP VIEW IF EXISTS `v_inventory_transaction`*/;
SET @saved_cs_client     = @@character_set_client;
/*!50503 SET character_set_client = utf8mb4 */;
/*!50001 CREATE VIEW `v_inventory_transaction` AS SELECT 
 1 AS `transaction_id`,
 1 AS `transaction_type`,
 1 AS `transaction_type_name`,
 1 AS `material_code`,
 1 AS `material_name`,
 1 AS `batch_no`,
 1 AS `warehouse_id`,
 1 AS `warehouse_name`,
 1 AS `location_id`,
 1 AS `location_name`,
 1 AS `quantity`,
 1 AS `before_quantity`,
 1 AS `after_quantity`,
 1 AS `unit_cost`,
 1 AS `amount`,
 1 AS `source_type`,
 1 AS `source_no`,
 1 AS `transaction_time`,
 1 AS `operator_name`,
 1 AS `remark`*/;
SET character_set_client = @saved_cs_client;

