--
-- Final view structure for view `v_inventory_transaction`
--

/*!50001 DROP VIEW IF EXISTS `v_inventory_transaction`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_inventory_transaction` AS select `t`.`transaction_id` AS `transaction_id`,`t`.`transaction_type` AS `transaction_type`,(case `t`.`transaction_type` when 'inbound' then '入库' when 'outbound' then '出库' when 'transfer_in' then '调拨入库' when 'transfer_out' then '调拨出库' when 'adjust' then '盘盈盘亏' end) AS `transaction_type_name`,`t`.`material_code` AS `material_code`,`t`.`material_name` AS `material_name`,`t`.`batch_no` AS `batch_no`,`t`.`warehouse_id` AS `warehouse_id`,`w`.`warehouse_name` AS `warehouse_name`,`t`.`location_id` AS `location_id`,`l`.`location_name` AS `location_name`,`t`.`quantity` AS `quantity`,`t`.`before_quantity` AS `before_quantity`,`t`.`after_quantity` AS `after_quantity`,`t`.`unit_cost` AS `unit_cost`,`t`.`amount` AS `amount`,`t`.`source_type` AS `source_type`,`t`.`source_no` AS `source_no`,`t`.`transaction_time` AS `transaction_time`,`t`.`operator_name` AS `operator_name`,`t`.`remark` AS `remark` from ((`inventory_transaction` `t` left join `inventory_warehouse` `w` on((`t`.`warehouse_id` = `w`.`warehouse_id`))) left join `inventory_storage_location` `l` on((`t`.`location_id` = `l`.`location_id`))) */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;

